#!/usr/bin/env python3
"""Render the circuit's ``main`` component from :mod:`zkfl.config`.

Keeping the instantiation generated rather than hand-written is what stops the
circuit and the Python trainer from drifting: there is exactly one place where
``n_features``, ``batch_size`` and the bit widths are written down.
"""
from __future__ import annotations

import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent.parent))

from zkfl.config import FixedPointConfig, DEFAULT_FP

TEMPLATE = """pragma circom 2.1.6;

// Generated by scripts/gen_circuit_main.py from zkfl/config.py -- do not edit.
// {name}

include "../lib/update_check.circom";

component main {{public [wOld, bOld, wNew, bNew, eta, dataRoot]}} =
    ModelUpdateCheck({n}, {k}, {depth}, {scale}, {x_bits}, {w_bits}, {z_bits}, {max_delta});
"""


def render(fp: FixedPointConfig) -> str:
    fp.check()
    return TEMPLATE.format(
        name=fp.circuit_name(),
        n=fp.n_features,
        k=fp.batch_size,
        depth=fp.merkle_depth,
        scale=fp.scale,
        x_bits=fp.x_bits,
        w_bits=fp.w_bits,
        z_bits=fp.z_bits,
        max_delta=fp.max_delta,
    )


def write(fp: FixedPointConfig, out_dir: Path) -> Path:
    out_dir.mkdir(parents=True, exist_ok=True)
    path = out_dir / f"{fp.circuit_name()}.circom"
    path.write_text(render(fp))
    return path


if __name__ == "__main__":
    root = Path(__file__).resolve().parent.parent
    print(write(DEFAULT_FP, root / "circuits" / "main"))
